                if(kind == ContentKind.LegalDocument) { Assert(livePage.Body!.TextContent.Contains("321/2026-QĐ_%["),"Legal number absent.");var lookup=new HtmlParser().ParseDocument(await guest.GetStringAsync("/van-ban?q=321%2F2026-QD&agency=qa+cuc+quan+ly+dat+dai&type=quyet+dinh&field=dat+dai&issuedFrom=2026-10-12&issuedTo=2026-10-12"));Assert(lookup.QuerySelector("a[href^='/bai-viet/"+saved.ContentId+"']")!=null,"Typed normalized combined lookup failed."); }
                await Act(writer,saved.ContentId,"BeginEdit");var editing=await Form(writer,saved.ContentId);editing["Title"]="Hidden"+marker;editing["BodyHtml"]="<p>Hidden revision only</p>";
                if(kind == ContentKind.LegalDocument) editing["Metadata.Number"]="999/DRAFT"+marker;
                if(kind == ContentKind.DraftDocument) editing["Metadata.ConsultationEndDate"]="2027-01-01";
                if(kind == ContentKind.Announcement) editing["Metadata.Unit"]="Hidden unit"+marker;
                var changed=await Save(writer,editing);await Act(writer,saved.ContentId,"Submit");
                var unchanged=new HtmlParser().ParseDocument(await guest.GetStringAsync("/bai-viet/"+saved.ContentId));Assert(unchanged.QuerySelector("h1")?.TextContent.Trim()==form["Title"]&&!unchanged.Body!.TextContent.Contains("Hidden"+marker),"Typed draft leaked.");
                var hiddenSearch=await guest.GetStringAsync("/tim-kiem?q=Hidden"+marker+"&includeDraft=true");Assert(!hiddenSearch.Contains(saved.ContentId.ToString()),"Public query bypass leaked typed draft.");
                var pending=await Content(saved.ContentId);var token=(await Form(review,saved.ContentId))["__RequestVerificationToken"];using var oldApproval=await Action(review,saved.ContentId,"PublishApproved",approved.CurrentRevisionId,pending.RowVersion,token);Assert(!oldApproval.IsSuccessStatusCode,"Old typed approval reused.");
                await Act(review,saved.ContentId,"Approve");await Act(review,saved.ContentId,"PublishApproved");Assert(new HtmlParser().ParseDocument(await guest.GetStringAsync("/bai-viet/"+saved.ContentId)).QuerySelector("h1")?.TextContent.Trim()==editing["Title"],"New typed revision not published.");
                await Act(publisher,saved.ContentId,"Unpublish");using var withdrawn=await guest.GetAsync("/bai-viet/"+saved.ContentId);Assert(withdrawn.StatusCode==HttpStatusCode.NotFound,"Typed withdrawal failed.");await Act(publisher,saved.ContentId,"RestoreRevision",approved.CurrentRevisionId);Assert(!(await Content(saved.ContentId)).IsPublic,"Typed restore republished.");
            });
            await Check("Permission revocation in already authenticated session immediately blocks sensitive action", async () =>
            {
                var form=await Form(publisher);form["Title"]="QA revoke active session";form["BodyHtml"]="<p>Kiểm tra quyền hiện thời</p>";form["CategoryId"]=firstCategory.ToString();var saved=await Save(publisher,form);var edit=await Form(publisher,saved.ContentId);await using(var db=new PortalDbContext(options)){var roleIds=await db.UserRoles.Where(x=>x.UserId==direct.Id).Select(x=>x.RoleId).ToArrayAsync();var claims=await db.RoleClaims.Where(x=>roleIds.Contains(x.RoleId)&&x.ClaimType=="permission"&&x.ClaimValue==Permissions.PublishDirect).ToListAsync();db.RoleClaims.RemoveRange(claims);await db.SaveChangesAsync();}
                using var denied=await Action(publisher,saved.ContentId,"PublishDirect",saved.CurrentRevisionId,saved.RowVersion,edit["__RequestVerificationToken"]);Assert(denied.StatusCode==HttpStatusCode.Forbidden,"Stale cookie retained revoked publish permission.");Assert(!(await Content(saved.ContentId)).IsPublic,"Permission revocation still published content.");
            });
            await Check("History UI shows current workflow state and exact audit revision links behind private access",async()=>
            {
                var latest=await Content(contentId);var history=new HtmlParser().ParseDocument(await publisher.GetStringAsync("/admin/history/"+contentId));Assert(history.Body!.TextContent.Contains("Hiện tại")&&history.Body.TextContent.Contains("Bản nháp"),"History did not label current revision state.");Assert(history.QuerySelectorAll("a[href^='/admin/preview/"+contentId+"?revisionId=']").Any(x=>x.GetAttribute("href")!.Contains(latest.CurrentRevisionId!.Value.ToString())),"History current revision private link missing.");await using var db=new PortalDbContext(options);var withdrawn=await db.AuditLogs.AsNoTracking().SingleAsync(x=>x.ContentId==contentId&&x.Action=="Unpublish");Assert(withdrawn.RevisionId.HasValue&&history.QuerySelectorAll("a[href*='revisionId="+withdrawn.RevisionId+"']").Any(),"History did not link exact withdrawn audit revision.");using var anon=await guest.GetAsync("/admin/history/"+contentId);Assert(anon.StatusCode is HttpStatusCode.Redirect or HttpStatusCode.Forbidden,"Anonymous history was exposed.");
            });
            // UI runs while the real Test web server is alive; random test credentials remain ignored.
            if(runBrowser) {
            var uiState=Path.Combine(root,".local","tests","phase2a","ui-credentials.json");await File.WriteAllTextAsync(uiState,JsonSerializer.Serialize(new{baseUrl,database="LandPortal_Test",password,writer=editor.UserName,reviewer=reviewer.UserName,direct=direct.UserName,contentId,image,imageName,pdf,pdfName},new JsonSerializerOptions{WriteIndented=true}));
            var node=new ProcessStartInfo("node"){WorkingDirectory=root,UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};node.ArgumentList.Add(Path.Combine(root,"tests","browser","cms-check.mjs"));using var ui=Process.Start(node)??throw new InvalidOperationException("UI test could not start.");var uiOutput=ui.StandardOutput.ReadToEndAsync();var uiError=ui.StandardError.ReadToEndAsync();await ui.WaitForExitAsync();var uiLog=await uiOutput+"\n"+await uiError;await File.WriteAllTextAsync(Path.Combine(evidence,"ui-run.log"),uiLog);Console.WriteLine(uiLog);Assert(ui.ExitCode==0,"2A SQL-backed browser UI tests failed; inspect private evidence.");
            var typedNode = new ProcessStartInfo("node") { WorkingDirectory = root, UseShellExecute = false, CreateNoWindow = true, RedirectStandardOutput = true, RedirectStandardError = true };
            typedNode.ArgumentList.Add(Path.Combine(root, "tests", "browser", "content-check.mjs"));
            using var typedUi = Process.Start(typedNode) ?? throw new InvalidOperationException("Typed content browser test could not start.");
            var typedOutput = typedUi.StandardOutput.ReadToEndAsync(); var typedError = typedUi.StandardError.ReadToEndAsync(); await typedUi.WaitForExitAsync();
            var typedLog = await typedOutput + "\n" + await typedError; var typedEvidence = TestEvidencePaths.At(root, "phase2b", "content-ui"); Directory.CreateDirectory(typedEvidence);
            await File.WriteAllTextAsync(Path.Combine(typedEvidence, "browser-run.log"), typedLog); Console.WriteLine(typedLog);
            Assert(typedUi.ExitCode == 0, "2B typed content SQL-backed browser tests failed; inspect ignored evidence.");
            } else checks.Add(new{name="Browser UI",status="NOT RUN",reason="Focused final HTTP query/permission rerun; previous 40-page browser evidence retained."});
        }
        catch(Exception e){checks.Add(new{name="Stopped HTTP/UI suite",status="FAIL",detail=e.Message});throw;}
        finally { if(!process.HasExited)process.Kill(entireProcessTree:true);await process.WaitForExitAsync();await File.WriteAllTextAsync(Path.Combine(evidence,"http-web.log"),await output+"\n"+await error);await File.WriteAllTextAsync(Path.Combine(evidence,"http-report.json"),JsonSerializer.Serialize(new{database="LandPortal_Test",utc=DateTimeOffset.UtcNow,checks},new JsonSerializerOptions{WriteIndented=true})); }
